// The example house's fictional files through the production readers, and its
// /example/ offline worker in a fake worker scope. Generated bytes, in-memory
// stores, fake transports and temporary folders only: no browser, IndexedDB,
// network, native host, real household or device evidence.
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { build } from 'vite';
import { writeExampleWorker } from '../build/example-offline-plugin.mjs';

assert.deepEqual(process.argv.slice(2), []);
const root = fileURLToPath(new URL('../../', import.meta.url));
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const pdf = bytes => Buffer.from(bytes.subarray(0, 5)).toString('latin1') === '%PDF-';
// No IndexedDB exists here; the example's copy store must not need one.
assert.equal(globalThis.indexedDB, undefined);

const scratch = mkdtempSync(join(tmpdir(), 'example-files-'));
try {
  let api;
  {
    const entry = join(scratch, 'entry.ts');
    writeFileSync(entry, [
      `export { createExampleElectrical, createExampleHomeboxOriginals, LAMP_MANUAL, LAMP_MANUAL_BYTES } from ${JSON.stringify(join(root, 'frontend/example/files.ts'))};`,
      `export { exampleHomeView, EXAMPLE_SCOPE } from ${JSON.stringify(join(root, 'frontend/example/household.ts'))};`,
      `export { buildSyntheticAtlas } from ${JSON.stringify(join(root, 'frontend/lantern-tests/unified-atlas/synthetic-atlas.ts'))};`,
    ].join('\n'));
    const result = await build({ root: join(root, 'frontend'), configFile: false, logLevel: 'silent',
      build: { write: false, target: 'node26', lib: { entry, formats: ['es'] }, rolldownOptions: { output: { codeSplitting: false } }, minify: false } });
    const path = join(scratch, 'fixture.mjs');
    writeFileSync(path, (Array.isArray(result) ? result[0] : result).output.find(row => row.type === 'chunk' && row.isEntry).code);
    api = await import(pathToFileURL(path).href);
  }
  const generated = await api.buildSyntheticAtlas(api.EXAMPLE_SCOPE);
  const view = api.exampleHomeView(generated.companion), signal = new AbortController().signal;

  // HomeBox-style original: listed on the reading lamp, read and kept through the production owner.
  const lamp = view.entries.find(entry => entry.entity.name === 'Fictional reading lamp');
  assert.deepEqual(lamp.attachments, [api.LAMP_MANUAL]);
  assert.equal(api.LAMP_MANUAL.byteSize, String(api.LAMP_MANUAL_BYTES.byteLength));
  assert.ok(pdf(api.LAMP_MANUAL_BYTES) && api.LAMP_MANUAL_BYTES.byteLength < 2_000);
  assert.equal(view.entries.filter(entry => entry.attachments.length > 0).length, 1);
  const documents = { createReader: () => Promise.reject(new Error('not used')) };
  let requests = 0;
  const served = () => requests;
  const originals = await api.createExampleHomeboxOriginals(view, documents, () => { requests++; });
  const created = await originals.createReader(view, signal);
  assert.equal(created.status, 'ok');
  const reader = created.value;
  const ref = { source: 'homebox-attachment', sourceInstanceId: lamp.source.sourceInstanceId, collectionId: lamp.source.collectionId,
    entityId: lamp.source.externalId, attachmentId: api.LAMP_MANUAL.attachmentId };
  assert.equal((await reader.open({ ...ref, attachmentId: '00000000-0000-4000-8000-0000000e0aff' }, signal)).status, 'missing');
  const opened = await reader.open(ref, signal);
  assert.equal(opened.status, 'ok');
  const blob = reader.getBlob(opened.frame), bytes = new Uint8Array(await blob.arrayBuffer());
  assert.equal(blob.type, 'application/pdf');
  assert.equal(sha(bytes), sha(api.LAMP_MANUAL_BYTES));
  const retained = reader.retain(opened.frame);
  assert.equal(retained.status, 'ok');
  assert.equal((await retained.value.result).status, 'ok');
  assert.equal((await retained.value.reconcile(signal)).status, 'held');
  // A second open in the same page reuses the same observation; the bytes are not read again.
  const again = await reader.open(ref, signal);
  assert.equal(again.status, 'ok');
  assert.equal(sha(new Uint8Array(await reader.getBlob(again.frame).arrayBuffer())), sha(api.LAMP_MANUAL_BYTES));
  assert.equal(served(), 1);
  reader.release(again.frame); reader.release(opened.frame); reader.dispose();
  assert.equal((await originals.createReader({ ...view }, signal)).status, 'retired');

  // Electrical drawing: the existing fictional fixture placed on the example's house building.
  const house = generated.companion.buildings.find(row => row.buildingId === 'syn-building-house');
  const electrical = await api.createExampleElectrical(view, { nativePlaceId: house.nativePlaceId, label: house.label });
  assert.deepEqual(electrical.scope, api.EXAMPLE_SCOPE);
  const listed = await electrical.topology.listAll(electrical.topology.getBinding(), 'location-semantics', signal);
  assert.deepEqual(listed.records.map(row => [row.payload.atlasId, row.payload.label]), [[house.nativePlaceId, 'Synthetic house']]);
  const library = await electrical.port.createReader();
  const frame = await library.read(house.nativePlaceId, signal);
  assert.equal(frame.status, 'available');
  assert.equal(frame.documents.length, 1);
  const [drawing] = frame.documents;
  assert.ok(drawing.pages.length > 0);
  const client = library.createDrawingClient(frame), held = await client.open(drawing.evidenceId, signal);
  const drawingBytes = new Uint8Array(await client.getBlob(held).arrayBuffer());
  assert.ok(pdf(drawingBytes));
  assert.equal(sha(drawingBytes), drawing.sha256);
  client.release(held); client.dispose(); library.release(frame); library.dispose();

  // Offline worker: exact table of the example's build files, served from its own cache.
  const out = join(scratch, 'dist-example');
  mkdirSync(join(out, 'assets'), { recursive: true });
  const files = { 'index.html': '<!doctype html><title>Synthetic example house</title>', 'assets/app-a1.js': 'export {};', 'assets/app-a1.css': 'body{}' };
  for (const [name, text] of Object.entries(files)) writeFileSync(join(out, name), text);
  const table = writeExampleWorker(out);
  assert.deepEqual(table.map(row => row.path), ['/example/assets/app-a1.css', '/example/assets/app-a1.js', '/example/index.html']);
  assert.throws(() => { writeFileSync(join(out, 'notes.txt'), 'x'); writeExampleWorker(out); }, /Unsupported example file/);
  rmSync(join(out, 'notes.txt'));
  writeExampleWorker(out);
  const workerCode = readFileSync(join(out, 'service-worker.js'), 'utf8');
  const MIME = { html: 'text/html; charset=utf-8', js: 'text/javascript; charset=utf-8', css: 'text/css; charset=utf-8' };
  const origin = 'https://example-host.invalid';
  async function scope({ served = files, preexisting = [] } = {}) {
    const stores = new Map(preexisting.map(name => [name, new Map()])), handlers = {}, requests = [];
    const network = { online: true };
    const caches = {
      async open(name) {
        if (!stores.has(name)) stores.set(name, new Map());
        const store = stores.get(name);
        return { match: async url => store.get(String(url))?.clone(), put: async (url, response) => { store.set(String(url), response); } };
      },
      keys: async () => [...stores.keys()], delete: async name => stores.delete(name),
    };
    const fetch = async (input, init = {}) => {
      const url = new URL(typeof input === 'string' ? input : input.url ?? String(input));
      requests.push({ path: url.pathname + url.search, credentials: init.credentials });
      if (!network.online) throw new TypeError('offline');
      const name = url.pathname.replace('/example/', '');
      if (url.origin !== origin || !(name in served)) return new Response(null, { status: 404 });
      return new Response(served[name], { headers: { 'content-type': MIME[name.split('.').at(-1)] } });
    };
    const self = { location: new URL(origin), skipWaiting: async () => {}, clients: { claim: async () => {} },
      addEventListener: (type, handler) => { handlers[type] = handler; } };
    new Function('self', 'caches', 'fetch', workerCode)(self, caches, fetch);
    const lifecycle = async type => { let work; handlers[type]({ waitUntil: promise => { work = promise; } }); await work; };
    const request = (path, mode = 'no-cors') => {
      let response = null;
      handlers.fetch({ request: { method: 'GET', url: origin + path, mode }, respondWith: value => { response = value; } });
      return response;
    };
    return { stores, requests, network, lifecycle, request };
  }
  const worker = await scope({ preexisting: ['houseatlas-example-old', 'houseatlas-saved-public-keep'] });
  await worker.lifecycle('install');
  assert.ok(worker.requests.every(row => row.credentials === 'omit'), 'install reads public files without cookies');
  await worker.lifecycle('activate');
  const names = [...worker.stores.keys()];
  assert.ok(names.includes('houseatlas-saved-public-keep') && !names.includes('houseatlas-example-old'), 'only older example caches are removed');
  worker.network.online = false;
  const entry = await worker.request('/example/index.html?building=syn-building-house&view=plan', 'navigate');
  assert.equal(await entry.text(), files['index.html'], 'the entry opens offline with its starting-state query');
  assert.equal(await (await worker.request('/example/assets/app-a1.js')).text(), files['assets/app-a1.js']);
  for (const [path, mode] of [['/api/atlas/view', 'cors'], ['/', 'navigate'], ['/saved/index.html', 'navigate'],
    ['/example/assets/app-a1.js', 'navigate'], ['/example/assets/app-a1.js?x=1', 'no-cors'], ['/example/other.html', 'navigate']])
    assert.equal(worker.request(path, mode), null, `${path} (${mode}) is not intercepted`);
  worker.network.online = true;
  assert.equal(await (await worker.request('/example/index.html', 'navigate')).text(), files['index.html']);
  // Changed bytes fail installation and leave no partial example cache.
  const changed = await scope({ served: { ...files, 'assets/app-a1.js': 'export const changed = 1;' } });
  await assert.rejects(changed.lifecycle('install'), /Example file changed/);
  assert.deepEqual([...changed.stores.keys()], []);
} finally { rmSync(scratch, { recursive: true, force: true }); }
console.log('PASS fictional example files: HomeBox original kept in memory, electrical drawing PDF, and /example/ offline worker (pure)');
